. "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"

_choice_openssl_command() {
    openssl help 2>&1 | gawk '
        /^[ \t]*$/ { next }
        /commands/ { next }
        {
            for (i = 1; i <= NF; i++) {
                if ($i !~ /:$/) print $i
            }
        }
    ' | gawk '!seen[$0]++'
}

_choice_openssl_delegate() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return
    fi
    if [[ ${#argc__positionals[@]} -eq 1 ]]; then
        if [[ "$ARGC_CWORD" == -* ]]; then
            printf '%s\n' -help -version
        else
            _choice_openssl_command
        fi
        return
    fi
    local cmd="${argc__positionals[0]}"
    if [[ "$ARGC_CWORD" == -* ]]; then
        local options
        options="$(openssl list -options "$cmd" 2>/dev/null)"
        # Digest commands share the dgst options but expose no option list.
        if [[ -z "$options" ]] && openssl list -1 -digest-commands 2>/dev/null | grep -qxF -- "$cmd"; then
            options="$(openssl list -options dgst 2>/dev/null)"
        fi
        printf '%s\n' "$options" | gawk '/^[^ \t]/ { sub(/[ \t].*/, ""); print "-" $0 }'
        return
    fi
    _argc_util_comp_path
}
